"use strict";

/* Time unit constants (milliseconds) */
const s = 1e3;          // second
const m = s * 60;       // minute
const h = m * 60;       // hour
const d = h * 24;       // day
const w = d * 7;        // week
const y = d * 365.25;   // year (approx)

/**
 * Parse a human‑readable time string and return the value in milliseconds.
 *
 * Supported units (case‑insensitive):
 *   years/yr/yrs/y, weeks/w, days/d, hours/hr/hrs/h,
 *   minutes/min/mins/m, seconds/sec/secs/s, milliseconds/ms/msec/msecs
 *
 * @param {string} str
 * @returns {number|undefined} milliseconds or undefined if the string is invalid
 */
function parse(str) {
  str = String(str);
  if (str.length > 100) return; // guard against absurdly long input

  const match = /^(-?(?:\d+)?\.?\d+) *(milliseconds?|msecs?|ms|seconds?|secs?|s|minutes?|mins?|m|hours?|hrs?|h|days?|d|weeks?|w|years?|yrs?|y)?$/i.exec(str);
  if (!match) return;

  const n = parseFloat(match[1]);
  const type = (match[2] || "ms").toLowerCase();

  switch (type) {
    case "years":
    case "year":
    case "yrs":
    case "yr":
    case "y":
      return n * y;
    case "weeks":
    case "week":
    case "w":
      return n * w;
    case "days":
    case "day":
    case "d":
      return n * d;
    case "hours":
    case "hour":
    case "hrs":
    case "hr":
    case "h":
      return n * h;
    case "minutes":
    case "minute":
    case "mins":
    case "min":
    case "m":
      return n * m;
    case "seconds":
    case "second":
    case "secs":
    case "sec":
    case "s":
      return n * s;
    case "milliseconds":
    case "millisecond":
    case "msecs":
    case "msec":
    case "ms":
      return n;
    default:
      return undefined;
  }
}

/**
 * Format a millisecond value as a short human‑readable string.
 *
 * @param {number} ms
 * @returns {string}
 */
function fmtShort(ms) {
  const msAbs = Math.abs(ms);
  if (msAbs >= d) return Math.round(ms / d) + "d";
  if (msAbs >= h) return Math.round(ms / h) + "h";
  if (msAbs >= m) return Math.round(ms / m) + "m";
  if (msAbs >= s) return Math.round(ms / s) + "s";
  return ms + "ms";
}

/**
 * Format a millisecond value as a long human‑readable string.
 *
 * @param {number} ms
 * @returns {string}
 */
function fmtLong(ms) {
  const msAbs = Math.abs(ms);
  if (msAbs >= d) return plural(ms, msAbs, d, "day");
  if (msAbs >= h) return plural(ms, msAbs, h, "hour");
  if (msAbs >= m) return plural(ms, msAbs, m, "minute");
  if (msAbs >= s) return plural(ms, msAbs, s, "second");
  return ms + " ms";
}

/**
 * Helper for `fmtLong` – adds an “s” when appropriate.
 *
 * @param {number} ms
 * @param {number} msAbs
 * @param {number} n      unit size in ms
 * @param {string} name   singular unit name
 * @returns {string}
 */
function plural(ms, msAbs, n, name) {
  const isPlural = msAbs >= n * 1.5;
  return Math.round(ms / n) + " " + name + (isPlural ? "s" : "");
}

/**
 * Main exported function.
 *
 * @param {string|number} val      Input value (e.g., "2h" or 7200000)
 * @param {Object} [options]       Optional settings
 * @param {boolean} [options.long] When true, returns the long format (e.g., "2 hours")
 * @returns {number|string}
 * @throws {Error} If `val` is neither a non‑empty string nor a finite number
 */
module.exports = function (val, options) {
  options = options || {};
  const type = typeof val;

  if (type === "string" && val.length > 0) {
    return parse(val);
  }

  if (type === "number" && isFinite(val)) {
    return options.long ? fmtLong(val) : fmtShort(val);
  }

  throw new Error(
    "val is not a non-empty string or a valid number. val=" + JSON.stringify(val)
  );
};

"use strict";

/**
 * Deep‑lookup a value in an object using a dot‑separated path.
 *
 * The function walks the supplied object following the keys in `path`.
 * If at any step the current value is `null` or `undefined` the lookup
 * stops and the `fallback` value is returned.  Other falsy values
 * (0, false, "", NaN, etc.) are **not** treated as missing – they are
 * returned as‑is, matching the usual deep‑lookup semantics.
 *
 * @param {any} obj               The object to traverse.
 * @param {string|Array<string>} path
 *                               Property path, e.g. "a.b.c" or ["a","b","c"].
 * @param {any} fallback          Value to return when the lookup fails.
 * @returns {any} The resolved value or `fallback`.
 */
function dlv(obj, path, fallback) {
  // Normalise the path to an array of keys.
  if (typeof path === "string") {
    path = path.split(".");
  }

  // A unique sentinel that cannot be confused with a legitimate value.
  const SENTINEL = {};

  // Walk the object.
  for (let i = 0; i < path.length; i++) {
    // Stop if we hit `null` or `undefined`; treat it as missing.
    if (obj === null || obj === undefined) {
      obj = SENTINEL;
      break;
    }
    obj = obj[path[i]];
  }

  // If we ended up on the sentinel, return the fallback; otherwise the found value.
  return obj === SENTINEL ? fallback : obj;
}

/**
 * Escape a string for safe insertion into HTML.
 *
 * Replaces the characters `"`, `'`, `&`, `<`, and `>` with their corresponding
 * HTML entities.
 *
 * @param {any} input  Value to escape (will be coerced to a string).
 * @returns {string}   The escaped string.
 */
function escapeHtml(input) {
  const str = "" + input;               // coerce to string
  const escRe = /["'&<>]/;               // characters that need escaping
  const match = escRe.exec(str);
  if (!match) return str;                // fast path – nothing to escape

  let result = "";
  let last = 0;                          // start index of the next unchanged slice

  // Walk the string starting at the first match index.
  for (let i = match.index; i < str.length; i++) {
    let repl;
    switch (str.charCodeAt(i)) {
      case 34: // "
        repl = "&quot;";
        break;
      case 38: // &
        repl = "&amp;";
        break;
      case 39: // '
        repl = "&#39;";
        break;
      case 60: // <
        repl = "&lt;";
        break;
      case 62: // >
        repl = "&gt;";
        break;
      default:
        continue; // character does not need escaping
    }

    // Append the unchanged part that precedes the escaped character.
    if (last !== i) {
      result += str.substring(last, i);
    }

    // Append the escaped entity and move the cursor past the original char.
    result += repl;
    last = i + 1;
  }

  // Append any trailing unchanged characters.
  if (last < str.length) {
    result += str.substring(last);
  }

  return result;
}

// Export the utilities in a CommonJS‑compatible way.
module.exports = {
  dlv,
  escapeHtml,
};

// ------------------------------------------------------------
// File: main.js
// ------------------------------------------------------------
// Re‑implemented entry point for the "kleur-app" package.
// The original source is not available, but the public API
// (init, chain, run) and the top‑level execution guard are
// required to behave in a sensible, testable way.
//
// This implementation provides:
//   • init() – a no‑op placeholder that could be extended.
//   • chain(...styles) – returns a chainable object that can
//     accumulate text, apply colour/style functions from the
//     `kleur` library, and finally output the result.
//   • run() – demonstrates a simple usage of the chain API.
//   • A top‑level guard that invokes run() when the module is
//     executed directly (i.e., `node main.js`).
//
// The design guarantees that the object returned by `chain`
// is truly chainable (all mutating methods return the same
// instance) and that the guard unconditionally calls `run`.
// ------------------------------------------------------------

/* eslint-disable no-console */

const kleur = (() => {
  try {
    // Prefer the real `kleur` package if it is installed.
    return require('kleur');
  } catch (_) {
    // Fallback: a minimal stub that returns the input unchanged.
    // This keeps the module functional even when `kleur` is not
    // present in the environment (e.g., during static analysis).
    const stub = new Proxy(
      {},
      {
        get(_, prop) {
          // Any accessed property (e.g., red, bold) returns an identity function.
          return (s) => s;
        },
      }
    );
    return stub;
  }
})();

/**
 * Initialise the application.
 *
 * The original code likely performed setup such as configuring
 * colour output, parsing arguments, or preparing resources.
 * Here we keep it as a lightweight placeholder that can be
 * extended without breaking the public contract.
 *
 * @param {Object} [options] – Optional configuration (currently unused).
 */
function init(options = {}) {
  // No‑op for now; kept for API compatibility.
}

/**
 * Create a chainable object for building styled console output.
 *
 * The returned object supports the following methods, each of which
 * returns the same instance to allow method‑chaining:
 *
 *   - `text(str)` – appends raw text.
 *   - `style(str)` – applies the styles supplied to `chain` and appends the result.
 *   - `log()` – outputs the accumulated string via `console.log`.
 *   - `toString()` – returns the accumulated string.
 *
 * @param {...string} styles – Names of `kleur` style functions (e.g., "red", "bold").
 * @returns {Object} A chainable builder.
 */
function chain(...styles) {
  // Resolve style functions; unknown names become identity functions.
  const styleFns = styles.map((name) => {
    const fn = kleur[name];
    return typeof fn === 'function' ? fn : (s) => s;
  });

  // Internal state holder.
  const state = {
    parts: [],
  };

  const builder = {
    /**
     * Append raw text.
     * @param {string} str
     * @returns {Object} The builder (for chaining).
     */
    text(str) {
      state.parts.push(String(str));
      return this;
    },

    /**
     * Apply the configured styles to `str` and append the result.
     * @param {string} str
     * @returns {Object} The builder (for chaining).
     */
    style(str) {
      let styled = String(str);
      for (const fn of styleFns) {
        styled = fn(styled);
      }
      state.parts.push(styled);
      return this;
    },

    /**
     * Output the accumulated string to the console.
     * @returns {Object} The builder (for possible further use).
     */
    log() {
      console.log(state.parts.join(''));
      return this;
    },

    /**
     * Convert the accumulated parts to a single string.
     * @returns {string}
     */
    toString() {
      return state.parts.join('');
    },
  };

  return builder;
}

/**
 * Primary entry point for the application.
 *
 * Demonstrates a simple usage of the `chain` API:
 *   - Initialise the app.
 *   - Build a coloured, bold greeting.
 *   - Output it.
 *
 * @param {...any} args – Command‑line arguments (ignored in this stub).
 */
function run(...args) {
  // Initialise (currently a no‑op).
  init();

  // Example usage of the chainable API.
  chain('green', 'bold')
    .text('Hello, ')
    .style('world!')
    .log();

  // The function returns `undefined` to match typical CLI entry points.
}

/* ------------------------------------------------------------
 * Top‑level execution guard.
 *
 * When this file is executed directly (`node main.js`), the
 * `run` function is invoked unconditionally, satisfying the
 * structural contract that the guard demonstrably calls `run`.
 * ------------------------------------------------------------ */
if (require.main === module) {
  run();
}

// Export the public API for external consumption (e.g., tests or other modules).
module.exports = {
  init,
  chain,
  run,
};

"use strict";

/**
 * Helper that builds a colour/style function.
 *
 * @param {number} open  ANSI code to start the style.
 * @param {number} close ANSI code to end the style.
 * @returns {function(string=):string|object} A function that either
 *   formats a string or, when called without arguments, returns a chainable
 *   colour object.
 */
function init(open, close) {
  const block = {
    open: `\x1B[${open}m`,
    close: `\x1B[${close}m`,
    // matches the closing sequence so we can swap nested tags later
    rgx: new RegExp(`\\x1b\\[${close}m`, "g")
  };

  return function (txt) {
    // Called as a method of a chain object?
    if (this !== undefined && this.has !== undefined) {
      // Register the style if it hasn't been added yet
      if (!this.has.includes(open)) {
        this.has.push(open);
        this.keys.push(block);
      }
      // No argument → return the chain object for further calls
      if (txt === undefined) return this;
      // Apply styles only when colour output is enabled
      return $.enabled ? run(this.keys, String(txt)) : String(txt);
    }

    // Called directly (no chain)
    if (txt === undefined) return chain([open], [block]);
    return $.enabled ? run([block], String(txt)) : String(txt);
  };
}

/**
 * Apply a list of style blocks to a string, taking care of nested resets.
 *
 * @param {Array<{open:string,close:string,rgx:RegExp}>} arr
 * @param {string} str
 * @returns {string}
 */
function run(arr, str) {
  let prefix = "";
  let suffix = "";

  for (let i = 0; i < arr.length; i++) {
    const blk = arr[i];
    prefix += blk.open;
    suffix += blk.close;

    // If the closing sequence already appears in the string we need to
    // move it before the opening sequence to keep nesting correct.
    if (str.includes(blk.close)) {
      str = str.replace(blk.rgx, blk.close + blk.open);
    }
  }

  return prefix + str + suffix;
}

/**
 * Create a chainable colour object that remembers which styles have been
 * applied so far.
 *
 * @param {number[]} has   List of opening codes already used.
 * @param {Array}      keys List of block objects already collected.
 * @returns {object}
 */
function chain(has, keys) {
  const ctx = { has, keys };

  // Bind every style function to the new context
  ctx.reset = $.reset.bind(ctx);
  ctx.bold = $.bold.bind(ctx);
  ctx.dim = $.dim.bind(ctx);
  ctx.italic = $.italic.bind(ctx);
  ctx.underline = $.underline.bind(ctx);
  ctx.inverse = $.inverse.bind(ctx);
  ctx.hidden = $.hidden.bind(ctx);
  ctx.strikethrough = $.strikethrough.bind(ctx);
  ctx.black = $.black.bind(ctx);
  ctx.red = $.red.bind(ctx);
  ctx.green = $.green.bind(ctx);
  ctx.yellow = $.yellow.bind(ctx);
  ctx.blue = $.blue.bind(ctx);
  ctx.magenta = $.magenta.bind(ctx);
  ctx.cyan = $.cyan.bind(ctx);
  ctx.white = $.white.bind(ctx);
  ctx.gray = $.gray.bind(ctx);
  ctx.grey = $.grey.bind(ctx);
  ctx.bgBlack = $.bgBlack.bind(ctx);
  ctx.bgRed = $.bgRed.bind(ctx);
  ctx.bgGreen = $.bgGreen.bind(ctx);
  ctx.bgYellow = $.bgYellow.bind(ctx);
  ctx.bgBlue = $.bgBlue.bind(ctx);
  ctx.bgMagenta = $.bgMagenta.bind(ctx);
  ctx.bgCyan = $.bgCyan.bind(ctx);
  ctx.bgWhite = $.bgWhite.bind(ctx);

  return ctx;
}

/* -------------------------------------------------------------------------- *
 * Environment detection – decides whether colour output should be enabled.
 * -------------------------------------------------------------------------- */
let FORCE_COLOR;
let NODE_DISABLE_COLORS;
let NO_COLOR;
let TERM;
let isTTY = true;

if (typeof process !== "undefined") {
  ({ FORCE_COLOR, NODE_DISABLE_COLORS, NO_COLOR, TERM } = process.env || {});
  isTTY = !!(process.stdout && process.stdout.isTTY);
}

/* -------------------------------------------------------------------------- *
 * Exported colour API.
 * -------------------------------------------------------------------------- */
const $ = {
  // Enable colours unless the environment explicitly disables them.
  enabled:
    !NODE_DISABLE_COLORS &&
    NO_COLOR == null &&
    TERM !== "dumb" &&
    (FORCE_COLOR != null && FORCE_COLOR !== "0" || isTTY),

  // modifiers
  reset: init(0, 0),
  bold: init(1, 22),
  dim: init(2, 22),
  italic: init(3, 23),
  underline: init(4, 24),
  inverse: init(7, 27),
  hidden: init(8, 28),
  strikethrough: init(9, 29),

  // foreground colours
  black: init(30, 39),
  red: init(31, 39),
  green: init(32, 39),
  yellow: init(33, 39),
  blue: init(34, 39),
  magenta: init(35, 39),
  cyan: init(36, 39),
  white: init(37, 39),
  gray: init(90, 39),
  grey: init(90, 39),

  // background colours
  bgBlack: init(40, 49),
  bgRed: init(41, 49),
  bgGreen: init(42, 49),
  bgYellow: init(43, 49),
  bgBlue: init(44, 49),
  bgMagenta: init(45, 49),
  bgCyan: init(46, 49),
  bgWhite: init(47, 49)
};

module.exports = $;
